package ru.neverland.townypolicies.model;
import java.util.*;
import ru.neverland.integration.PolicyEffects;
public record PolicyOption(String id,String name,String icon,List<String> advantages,List<String> disadvantages,Map<String,Double> effects,Set<String> requires,Set<String> production,Set<String> upkeep){
    public PolicyOption{if(id==null||!id.matches("[a-z_]{1,32}")||name==null||name.isBlank()||icon==null||icon.isBlank())throw new IllegalArgumentException("Неверный режим политики");advantages=List.copyOf(advantages);disadvantages=List.copyOf(disadvantages);effects=Map.copyOf(effects);requires=Set.copyOf(requires);production=Set.copyOf(production);upkeep=Set.copyOf(upkeep);if(advantages.isEmpty()||disadvantages.isEmpty()||!PolicyEffects.EFFECTS.containsAll(effects.keySet()))throw new IllegalArgumentException("Нужны плюсы, минусы и известные эффекты");for(var e:effects.entrySet()){double min=e.getKey().equals("happiness")?-20:e.getKey().equals("tariff")||e.getKey().equals("army")||e.getKey().equals("upkeep")?0:-.5;double max=e.getKey().equals("happiness")||e.getKey().equals("tariff")?20:.5;if(!Double.isFinite(e.getValue())||e.getValue()<min||e.getValue()>max)throw new IllegalArgumentException("Эффект вне диапазона: "+e.getKey());}for(String plugin:requires)if(!Set.of("NeverLandTownyBuilds","NeverLandTownyResources","NeverLandTownyPopulation","NeverLandTownyUpkeep","NeverLandTownyTrade","NeverLandTownyTaxes").contains(plugin))throw new IllegalArgumentException("Неизвестная зависимость");for(var targets:List.of(production,upkeep))for(String target:targets)if(!target.equals("*")&&!target.matches("[a-z0-9_]{1,64}"))throw new IllegalArgumentException("Неверный проект");}
    public double effect(String key){return effects.getOrDefault(key,0d);}
    public boolean targets(String project,boolean cost){var targets=cost?upkeep:production;return targets.contains("*")||targets.contains(project);}
}
